SELECT f.id, f.test_run_id, f.symbol, f.signal_id, f.stage, LEFT(f.payload, 700) AS payload FROM fix122_evaluation f WHERE f.test_run_id IS NOT NULL AND ((f.symbol = 'DOGEUSDT' AND f.payload LIKE '%candleOpenTime: 2026-10-12T01:01:00Z%') OR (f.symbol = 'EGLDUSDT' AND f.payload LIKE '%candleOpenTime: 2026-10-11T19:39:00Z%') OR (f.symbol = 'ACEUSDT' AND f.payload LIKE '%candleOpenTime: 2026-10-12T06:56:00Z%')) ORDER BY f.test_run_id, f.id LIMIT 60